private fun Throwable.fullMessage(): String = generateSequence(this as Throwable?) { it.cause }.mapNotNull { it.message }.joinToString(" | ")
private fun Throwable.isTransientContestNetworkError(): Boolean { val raw=fullMessage(); return listOf("Unable to resolve host","No address associated with hostname","timed out","timeout","connection reset","connection refused","temporarily unreachable","HTTP 502","HTTP 503","HTTP 504").any{raw.contains(it,true)} }
private suspend fun <T> contestPreflight(stage:String,block:suspend()->T):T{var last:Throwable?=null;repeat(3){attempt->try{return block()}catch(t:Throwable){last=t;if(!t.isTransientContestNetworkError()||attempt==2)throw IllegalStateException(stage+" failed after "+(attempt+1)+" attempt(s): "+t.fullMessage().ifBlank{t.javaClass.simpleName},t);delay(700L*(attempt+1))}};throw last?:IllegalStateException(stage+" failed.")}

@OptIn(ExperimentalMaterial3Api::class)
@Composable fun ProductionApp(wallet:WalletSession){
 val repo=remember{LiveRepository()};val context=LocalContext.current;var availableUpdate by remember{mutableStateOf<AppUpdate?>(null)}
 LaunchedEffect(Unit){val p=context.packageManager.getPackageInfo(context.packageName,0);val installed=if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.P)p.longVersionCode else {@Suppress("DEPRECATION") p.versionCode.toLong()};runCatching{AppUpdateRepository().latest()}.onSuccess{latest->if(latest!=null&&latest.versionCode.toLong()>installed)availableUpdate=latest}}
 var page by remember{mutableStateOf("home")};val goHome={page="home"};BackHandler(enabled=page!="home"){goHome()}
 availableUpdate?.let{u->AlertDialog(onDismissRequest={availableUpdate=null},title={Text("SPARKD update available")},text={Text("Version ${u.versionName} is ready. Update to get the latest fixes and contest features.")},confirmButton={Button({context.startActivity(Intent(Intent.ACTION_VIEW,Uri.parse(u.downloadUrl)))}){Text("Update now")}},dismissButton={TextButton({availableUpdate=null}){Text("Later")}})}
 Scaffold(topBar={CenterAlignedTopAppBar(navigationIcon={if(page!="home")IconButton(onClick=goHome){Icon(Icons.Default.ArrowBack,"Back to home")}},title={Text("SPARKD",fontWeight=FontWeight.Black)})},bottomBar={NavigationBar{Tab.entries.forEach{tab->val route=when(tab){Tab.Home->"home";Tab.Forge->"forge";Tab.Contest->"contest";Tab.Winners->"winners";Tab.Profile->"profile"};val icon=when(tab){Tab.Home->Icons.Default.Home;Tab.Forge->Icons.Default.Edit;Tab.Contest->Icons.Default.EmojiEvents;Tab.Winners->Icons.Default.WorkspacePremium;Tab.Profile->Icons.Default.Person};NavigationBarItem(selected=page==route,onClick={page=route},icon={Icon(icon,tab.label)},label={Text(tab.label)})};NavigationBarItem(selected=page=="submit",onClick={page="submit"},icon={Icon(Icons.Default.UploadFile,"Submit")},label={Text("Submit")})}}}){padding->when(page){"forge"->Box(Modifier.padding(padding)){Forge(wallet){page="entry"}};"contest"->Box(Modifier.padding(padding)){Contest(repo)};"submit"->Box(Modifier.padding(padding)){SubmitMeme{page="entry"}};"winners"->Box(Modifier.padding(padding)){Winners(repo)};"profile"->Box(Modifier.padding(padding)){Profile(wallet)};"entry"->Box(Modifier.padding(padding)){ContestEntry(wallet,repo)};else->LiveHome(Modifier.padding(padding),repo,wallet){page=it}}}
}

@Composable private fun LiveHome(modifier:Modifier,repo:LiveRepository,wallet:WalletSession,go:(String)->Unit){val scope=rememberCoroutineScope();var contest by remember{mutableStateOf<Contest?>(null)};var walletAddress by remember{mutableStateOf(wallet.address)};var message by remember{mutableStateOf("Loading the live SPARKD contest…")};LaunchedEffect(Unit){while(isActive){runCatching{repo.contest()}.onSuccess{contest=it;message=""}.onFailure{if(contest==null)message="Live contest data is temporarily unavailable. Retrying automatically…"};delay(15_000)}};LazyColumn(modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("Create. Enter. Equal chance. Win.",fontSize=30.sp,fontWeight=FontWeight.Black)};item{Text("Every eligible meme gets exactly one chance in SPARKD's automated random drawing.")};item{Text(if(walletAddress==null)"Connect your Solana wallet to participate." else "Wallet connected: "+walletAddress!!.take(6)+"…"+walletAddress!!.takeLast(4))};item{Card{Column(Modifier.padding(18.dp)){Text(contest?.phase?:"LIVE",fontWeight=FontWeight.Bold);Text(contest?.title?:message,fontSize=23.sp,fontWeight=FontWeight.Black);contest?.let{Text(it.prize)}}}};item{Button({if(walletAddress!=null)go("forge") else scope.launch{message="Opening your Solana wallet…";runCatching{wallet.connect()}.onSuccess{walletAddress=it;go("forge")}.onFailure{message=it.message?:"Wallet connection failed."}}},Modifier.fillMaxWidth()){Text(if(walletAddress==null)"🔥 Connect wallet & open Meme Forge" else "🔥 Open Meme Forge")}};item{Button({go("contest")},Modifier.fillMaxWidth()){Text("🎲 View eligible contenders")}};item{OutlinedButton({go("submit")},Modifier.fillMaxWidth()){Text("📤 Submit saved Forge meme")}};item{OutlinedButton({if(walletAddress!=null){wallet.disconnect();walletAddress=null;message="Wallet disconnected."}else scope.launch{runCatching{wallet.connect()}.onSuccess{walletAddress=it;message="Wallet connected."}.onFailure{message=it.message?:"Wallet connection failed."}}},Modifier.fillMaxWidth()){Text(if(walletAddress==null)"Connect Solana Wallet" else "Disconnect Wallet")}};if(message.isNotBlank())item{Text(message)}}}

@Composable private fun SubmitMeme(onReady:()->Unit){val context=LocalContext.current;var title by remember{mutableStateOf(ForgeDraft.submissionTitle)};var selectedPng by remember{mutableStateOf(ForgeDraft.exportedPng)};var record by remember{mutableStateOf(ForgeDraft.exportedRecord)};var status by remember{mutableStateOf(if(record==null)"Loading your saved Forge export…" else "Original SPARKD Forge export ready for entry.")};LaunchedEffect(Unit){if(selectedPng==null||record==null){runCatching{withContext(Dispatchers.IO){ForgeExportStore.load(context)}}.onSuccess{saved->if(saved!=null){selectedPng=saved.first;record=saved.second;ForgeDraft.exportedPng=saved.first;ForgeDraft.exportedRecord=saved.second;status="Verified SPARKD Forge export ready for contest entry."}else status="Create and export a meme in the SPARKD Meme Forge before submitting."}.onFailure{status="Saved Forge export could not be verified: ${it.message}"}}};LazyColumn(Modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("Submit a Meme",fontSize=28.sp,fontWeight=FontWeight.Black)};item{Text("Your latest verified SPARKD Meme Forge export is used automatically. Every accepted meme receives one equal chance in the weekly random drawing.")};item{OutlinedTextField(title,{title=it.take(80)},label={Text("Meme title")},modifier=Modifier.fillMaxWidth(),singleLine=true)};item{Text(status,color=if(record!=null&&selectedPng!=null)Green else Gold)};record?.let{forge->item{Card{Column(Modifier.padding(16.dp)){Text("Forge verification passed",fontWeight=FontWeight.Bold,color=Green);Text("Meme ID: "+forge.memeID);Text("Export wallet: "+if(forge.wallet=="NOT_CONNECTED")"Not connected during export" else forge.wallet.take(6)+"…"+forge.wallet.takeLast(4));Text("This verified Forge image is the contest entry. No vote count changes its chance of winning.")}}}};item{Button({ForgeDraft.submissionTitle=title.trim();onReady()},Modifier.fillMaxWidth(),enabled=record!=null&&selectedPng!=null&&title.isNotBlank()){Text("Continue to secure contest entry")}}}}

@Composable private fun ContestEntry(wallet:WalletSession,repo:LiveRepository){
 val scope=rememberCoroutineScope();val context=LocalContext.current;val api=remember{ContestBurnApi()};val recovery=remember{BurnRecoveryStore(context)};var confirmBurn by remember{mutableStateOf(false)};var submitting by remember{mutableStateOf(false)};var completed by remember{mutableStateOf(false)};var status by remember{mutableStateOf("Export a verified Forge PNG, then review the secure entry checks here.")};var prepared by remember{mutableStateOf<PreparedBurn?>(null)};var existingBurnSignature by remember{mutableStateOf<String?>(null)};val forge=ForgeDraft.exportedRecord;val bytes=ForgeDraft.exportedPng
 suspend fun finalizeExisting(burn:PreparedBurn,signature:String,record:ForgeDnaRecord,png:ByteArray):String{val address=wallet.address?:error("Reconnect your wallet before submitting.");status="Verifying the existing 2,000 SPARKD burn…";api.verifyBurn(address,signature);status="Uploading your selected verified Forge PNG…";val imagePath=api.uploadMeme(address,burn.contestId,png);status="Finalizing your selected meme with the existing burn receipt…";api.finalizeSubmission(address,burn,signature,record,ForgeDraft.submissionTitle,imagePath);recovery.clear();return signature}
 suspend fun finalizeNew(burn:PreparedBurn,record:ForgeDnaRecord,png:ByteArray):String{val address=wallet.address?:error("Reconnect your wallet before submitting.");status="Uploading the verified contest PNG…";val imagePath=api.uploadMeme(address,burn.contestId,png);val pending=recovery.pending();val signature=if(pending!=null){check(pending.wallet==address&&pending.contestId==burn.contestId){"A saved burn belongs to a different wallet or contest. DO NOT BURN AGAIN."};val saved=pending.transactionSignature;val expiry=pending.lastValidBlockHeight;if(saved!=null){status="Recovering the previously approved SPARKD burn…";val chain=api.transactionStatus(address,saved);when{chain.found&&!chain.failed->saved;chain.found&&chain.failed->{recovery.clear();error("The previously signed transaction failed on-chain. Review again to build a fresh transaction.")};expiry!=null&&api.currentBlockHeight(address)>expiry->{recovery.clear();prepared=null;error("The previously signed transaction expired without landing. Tap Review secure entry to build a fresh transaction.")};else->{val resent=api.resendSignedTransaction(address,burn.contestId,pending.signedTransaction);check(resent==saved){"Recovered transaction signature changed. DO NOT BURN AGAIN."};resent}}}else{recovery.clear();prepared=null;error("The saved transaction expired before broadcast. Tap Review secure entry to build a fresh transaction.")}}else{status="Waiting for wallet approval to sign exactly the reviewed 2,000 SPARKD burn…";val signed=wallet.signTransaction(burn.unsignedTransaction);recovery.save(burn.contestId,address,signed,lastValidBlockHeight=burn.lastValidBlockHeight);val sent=api.sendSignedTransaction(address,burn.contestId,signed,burn.unsignedTransaction,recovery);recovery.save(burn.contestId,address,signed,sent,burn.lastValidBlockHeight);sent};status="Verifying the exact 2,000 SPARKD burn on-chain…";api.verifyBurn(address,signature);status="Recording the verified burn receipt…";api.recordBurnReceipt(address,burn.contestId,signature);status="Finalizing your contest submission…";api.finalizeSubmission(address,burn,signature,record,ForgeDraft.submissionTitle,imagePath);recovery.clear();return signature}
 fun finish(signature:String){completed=true;runCatching{ForgeExportStore.clear(context)};ForgeDraft.exportedPng=null;ForgeDraft.exportedRecord=null;status="Contest entry submitted successfully. Your meme now has one equal chance in the random draw. Burn verified: "+signature.take(8)+"…"+signature.takeLast(8)}
 LazyColumn(Modifier.padding(20.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{Text("Secure Contest Entry",fontSize=28.sp,fontWeight=FontWeight.Black)};item{Text("Entry requires one 2,000 SPARKD burn per wallet and contest. Every finalized eligible meme gets exactly one equal chance in the automated draw.",color=androidx.compose.ui.graphics.Color.LightGray)};item{Card{Column(Modifier.padding(16.dp)){Text("Forge export",fontWeight=FontWeight.Bold);Text(forge?.memeID?:"No verified Forge export is available.");Text(if(bytes==null)"Export a meme from the Forge first." else "Verified PNG is retained on this device.")}}};item{Button({scope.launch{prepared=null;existingBurnSignature=null;status=if(wallet.address==null)"Waiting for wallet approval…" else "Checking contest entry…";runCatching{val address=wallet.address?:wallet.connect();val record=forge?:error("Export a verified Forge PNG first.");check(record.wallet==address||record.wallet=="NOT_CONNECTED"){"This Forge PNG was exported for a different wallet. Re-export after connecting this wallet."};val contest=contestPreflight("Live contest lookup"){repo.contest()};check(contest.id.isNotBlank()){"The live contest is unavailable."};check(contest.phase=="SUBMISSION"||contest.phase=="OPEN"){"Submissions are not open for the current contest."};check(!contestPreflight("Existing submission check"){api.hasExistingSubmission(address)}){"This wallet already has a finalized contest submission."};status="Verifying SPARKD Forge DNA…";contestPreflight("Forge DNA verification"){api.verifyForge(address,record,bytes?:error("Verified Forge PNG is missing."))};status="Checking whether this wallet already burned the contest entry fee…";val prior=contestPreflight("Existing burn check"){api.findExistingBurn(address,contest.id)};if(prior!=null){existingBurnSignature=prior;prepared=contestPreflight("Contest preparation"){api.prepareBurn(address)};status="Existing verified contest burn found. No second burn is required."}else{prepared=contestPreflight("Contest preparation"){api.prepareBurn(address)};status="Ready. Review and approve one 2,000 SPARKD burn to enter."}}.onFailure{status=it.fullMessage().ifBlank{"Unable to prepare contest entry."}}}},Modifier.fillMaxWidth(),enabled=!submitting&&!completed){Text("Review secure entry")}};prepared?.let{burn->item{Card{Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Contest entry review",fontWeight=FontWeight.Black);Text("Entry burn: 2,000 SPARKD");Text("Selection: one equal random chance");Text(if(existingBurnSignature!=null)"Existing burn will be reused — no second burn." else "Your wallet will be asked to sign exactly one reviewed burn transaction.");Button({confirmBurn=true},Modifier.fillMaxWidth(),enabled=!submitting&&!completed){Text(if(existingBurnSignature!=null)"Submit verified meme" else "Approve burn & submit")}}}}};if(confirmBurn&&prepared!=null){item{AlertDialog(onDismissRequest={if(!submitting)confirmBurn=false},title={Text("Confirm contest entry")},text={Text(if(existingBurnSignature!=null)"Submit this verified Forge meme using your existing contest burn?" else "Approve exactly one 2,000 SPARKD burn and submit this verified Forge meme? Every eligible meme receives one equal chance in the draw.")},confirmButton={Button({confirmBurn=false;submitting=true;scope.launch{runCatching{val record=forge?:error("Verified Forge export is missing.");val png=bytes?:error("Verified Forge PNG is missing.");val burn=prepared?:error("Review the entry again.");val signature=existingBurnSignature?.let{finalizeExisting(burn,it,record,png)}?:finalizeNew(burn,record,png);finish(signature)}.onFailure{status=it.fullMessage().ifBlank{"Contest submission failed."}};submitting=false}}){Text("Confirm")}},dismissButton={TextButton({confirmBurn=false}){Text("Cancel")}})}};item{Text(status,color=if(completed)Green else Gold)}}
}
